command:
task_tmp_base=${TMPDIR:?TMPDIR is required}
resolve_tmp=$(mktemp -d "$task_tmp_base/language-resolve.XXXXXX") || exit 1
cleanup() { rmdir -- "$resolve_tmp" 2>/dev/null || true; }
trap cleanup EXIT HUP INT TERM
TMPDIR="$resolve_tmp" UV_NO_CACHE=1 UV_NO_PROJECT=1 uv run ".agents/skills/kntnt/library/scripts/languages.py" resolve --scope=composition --scope=review --scope=anti-slop sv
